const rows = $input.all().map(item => item.json);

// Определяем период — последние 7 дней
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const formatDate = (d) => {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yy = String(d.getFullYear()).slice(2);
  return `${dd}.${mm}.${yy}`;
};

// Фильтруем за неделю
const recent = rows.filter(r => {
  if (!r.processed_at) return false;
  const d = new Date(r.processed_at);
  return d >= weekAgo && d <= now;
});

const total = recent.length;

if (total === 0) {
  return [{
    json: {
      telegram_message: '📊 <b>Отчёт по лидам за неделю</b>\n(' + formatDate(weekAgo) + ' — ' + formatDate(now) + ')\n\nНовых заявок не было.'
    }
  }];
}

// Считаем по категориям
const hot = recent.filter(r => r.category === 'hot').length;
const warm = recent.filter(r => r.category === 'warm').length;
const cold = recent.filter(r => r.category === 'cold').length;

// Средний score
const scores = recent.map(r => Number(r.score)).filter(s => !isNaN(s));
const avgScore = scores.length > 0
  ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1)
  : '—';

// Требуют немедленного ответа
const immediate = recent.filter(r => r.response_priority === 'immediate').length;

// Проценты
const pct = (n) => total > 0 ? Math.round(n / total * 100) : 0;

const message = `📊 <b>Отчёт по лидам за неделю</b>
(${formatDate(weekAgo)} — ${formatDate(now)})

Всего заявок: <b>${total}</b>
🔥 Горячих: ${hot} (${pct(hot)}%)
🟡 Тёплых: ${warm} (${pct(warm)}%)
🔵 Холодных: ${cold} (${pct(cold)}%)

Средний score: <b>${avgScore}/10</b>
Требуют немедленного ответа: <b>${immediate}</b>`;

return [{
  json: {
    telegram_message: message
  }
}];
